const clean = s => String(s == null ? '' : s).replace(/\s+/g, ' ').trim();
export const meaningHash = s => createHash('sha1').update(clean(s)).digest('hex').slice(0, 8);

/** The curated cues for this card, or null when there are none for its current meaning. */
export function curatedCues(id, meaning) {
  const e = Object.prototype.hasOwnProperty.call(GLOSSARY, id) ? GLOSSARY[id] : null;
  if (!e || !e.m.includes(meaningHash(meaning))) return null;
  return { es: e.es.slice(), en: e.en.slice() };
}
